const ultTratamiento = $('MySQL - Obtener Último Tratamiento').first().json;
const reglaRows = $input.all();
const regla = reglaRows.length > 0 ? reglaRows[0].json : { recommended_interval: 15, interval_unit: 'DIAS', description: 'Intervalo estándar' };

const fechaSesion = new Date(ultTratamiento.date);
const proxFecha = new Date(fechaSesion);

if (regla.interval_unit === 'DIAS') {
  proxFecha.setDate(proxFecha.getDate() + regla.recommended_interval);
} else if (regla.interval_unit === 'SEMANAS') {
  proxFecha.setDate(proxFecha.getDate() + (regla.recommended_interval * 7));
} else if (regla.interval_unit === 'MESES') {
  proxFecha.setMonth(proxFecha.getMonth() + regla.recommended_interval);
}

const proxFechaStr = proxFecha.toISOString().split('T')[0];

return [{
  json: {
    success: true,
    cliente: ultTratamiento.client_name,
    ultimoTratamiento: ultTratamiento.treatment_name,
    fechaUltima: ultTratamiento.date,
    intervalo: `${regla.recommended_interval} ${regla.interval_unit.toLowerCase()}`,
    proximaSesionCalculada: proxFechaStr,
    mensajeRecomendacion: `Tu última sesión de ${ultTratamiento.treatment_name} fue el ${ultTratamiento.date}. Según la frecuencia configurada para este tratamiento (${regla.recommended_interval} ${regla.interval_unit.toLowerCase()}), tu siguiente sesión corresponde el ${proxFechaStr}. ¿Deseas agendarla ahora?`
  }
}];
